INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Services > Management
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist das Management von Services in einem IT-System ohne spezielle Tools möglich?', 2, '[{"text": "Ja", "correct": true, "because": "Manuell möglich, aber ineffizient"}, {"text": "Nein", "correct": false, "because": "Tools sind hilfreich, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen alle Services eines Systems zentral verwaltet werden, um effizient zu sein?', 2, '[{"text": "Nein", "correct": true, "because": "Dezentrale Verwaltung ist ebenfalls möglich"}, {"text": "Ja", "correct": false, "because": "Zentralität ist praktisch, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Management von Services die Systemleistung negativ beeinflussen?', 2, '[{"text": "Ja", "correct": true, "because": "Überwachung kann Ressourcen beanspruchen"}, {"text": "Nein", "correct": false, "because": "Einfluss ist möglich, aber nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es möglich, Services ohne dokumentierte Managementprozesse stabil zu betreiben?', 2, '[{"text": "Ja", "correct": true, "because": "Technisch machbar, aber riskant"}, {"text": "Nein", "correct": false, "because": "Dokumentation ist sinnvoll, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Services ohne aktives Management automatisch wartungsfrei?', 2, '[{"text": "Nein", "correct": true, "because": "Wartung bleibt notwendig"}, {"text": "Ja", "correct": false, "because": "Management erleichtert, ist aber nicht alles"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird häufig für das Management von Services unter Linux verwendet?', 3, '[{"text": "systemd", "correct": true, "because": "Standard für Service-Verwaltung"}, {"text": "cron", "correct": false, "because": "Für Zeitsteuerung, nicht Management"}, {"text": "grep", "correct": false, "because": "Für Textsuche, nicht Services"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt das Service-Management in erster Linie?', 2, '[{"text": "Sicherstellung der Verfügbarkeit", "correct": true, "because": "Kernaufgabe des Managements"}, {"text": "Reduktion der Benutzeranzahl", "correct": false, "because": "Irrelevant"}, {"text": "Erhöhung der Entwicklungskosten", "correct": false, "because": "Gegenteil ist gewünscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft, den Status von Services zu überwachen?', 2, '[{"text": "Logging", "correct": true, "because": "Protokolliert Aktivitäten"}, {"text": "Debugging", "correct": false, "because": "Für Fehleranalyse, nicht Überwachung"}, {"text": "Partitionierung", "correct": false, "because": "Für Speicher, nicht Services"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann durch schlechtes Service-Management entstehen?', 3, '[{"text": "Service-Ausfall", "correct": true, "because": "Mangelnde Überwachung führt zu Problemen"}, {"text": "Schnellere Reaktionszeit", "correct": false, "because": "Unrealistisch"}, {"text": "Automatische Skalierung", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Konzept wird oft verwendet, um Service-Management-Prozesse zu standardisieren?', 2, '[{"text": "ITIL", "correct": true, "because": "Framework für IT-Service-Management"}, {"text": "ISO", "correct": false, "because": "Allgemeine Standards, nicht spezifisch"}, {"text": "Agile", "correct": false, "because": "Für Entwicklung, nicht Management"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben gehören zum Management von Services?', 4, '[{"text": "Überwachung", "correct": true, "because": "Stellt Betrieb sicher"}, {"text": "Konfiguration", "correct": true, "because": "Passt Services an"}, {"text": "Wartung", "correct": true, "because": "Hält Services funktionsfähig"}, {"text": "Hardware-Design", "correct": false, "because": "Nicht Teil des Managements"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools unterstützen das Service-Management?', 3, '[{"text": "Nagios", "correct": true, "because": "Überwacht Services"}, {"text": "Ansible", "correct": true, "because": "Automatisiert Konfiguration"}, {"text": "Zabbix", "correct": true, "because": "Monitoring-Lösung"}, {"text": "Photoshop", "correct": false, "because": "Für Grafik, nicht Services"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken entstehen durch unzureichendes Service-Management?', 4, '[{"text": "Systemausfälle", "correct": true, "because": "Fehlende Kontrolle"}, {"text": "Sicherheitslücken", "correct": true, "because": "Keine Updates"}, {"text": "Performanceverlust", "correct": true, "because": "Unoptimierte Services"}, {"text": "Geringere Installationszeit", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet effektives Service-Management?', 3, '[{"text": "Höhere Verfügbarkeit", "correct": true, "because": "Minimiert Ausfälle"}, {"text": "Kosteneffizienz", "correct": true, "because": "Optimiert Ressourcen"}, {"text": "Bessere Fehlererkennung", "correct": true, "because": "Durch Überwachung"}, {"text": "Weniger Dokumentation", "correct": false, "because": "Dokumentation bleibt wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind für das Service-Management essenziell?', 3, '[{"text": "Monitoring-Systeme", "correct": true, "because": "Erfassen Status"}, {"text": "Dokumentation", "correct": true, "because": "Nachvollziehbarkeit"}, {"text": "Automatisierungstools", "correct": true, "because": "Erleichtern Verwaltung"}, {"text": "Büroausstattung", "correct": false, "because": "Irrelevant"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Service-Management umfasst die Überwachung von Dienststatus. b) Services können ohne Management unbegrenzt stabil laufen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Überwachung ja, Stabilität nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Automatisierung im Service-Management reduziert menschliche Fehler. b) Service-Management ist nur bei großen Systemen relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Automatisierung ja, Management immer nützlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Service-Management kann Ausfallzeiten minimieren. b) Alle Services müssen manuell verwaltet werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ausfallzeiten ja, Automatisierung möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Dokumentation ist ein Teil des Service-Managements. b) Service-Management hat keinen Einfluss auf die Sicherheit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dokumentation ja, Sicherheit beeinflusst"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Schlechtes Service-Management kann zu Datenverlust führen. b) Service-Management ist unabhängig von der Systemgröße.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Datenverlust ja, Größe beeinflusst Ansatz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

